      OUTCOME_CONTRACEPTIVE:{severity:'normal',icon:'🟢',title:{en:'Contraceptive Use',np:'Contraceptive को प्रयोगको असर'},message:{en:'The source algorithm links irregular bleeding with recent contraceptive use.',np:'स्रोत एल्गोरिदमले अनियमित रक्तस्रावलाई गर्भनिरोधक प्रयोगसँग जोड्छ।'},action:{en:'Assess contraceptive use, counsel and manage according to current family-planning guidance.',np:'गर्भनिरोधक प्रयोग मूल्याङ्कन गरी हालको family-planning guidance अनुसार सल्लाह तथा व्यवस्थापन गर्नुहोस्।'}},
      OUTCOME_SUSPECTED_CANCER:{severity:'danger',icon:'🚨',title:{en:'Suspected Cancer',np:'सम्भावित Cancer'},message:{en:'The source algorithm recommends referral to a hospital for cancer investigation.',np:'स्रोत एल्गोरिदमले cancer जाँचका लागि अस्पतालमा प्रेषण गर्न भन्छ।'},action:{en:'Refer for investigation according to current gynecologic cancer guidance.',np:'हालको gynecologic cancer guidance अनुसार जाँचका लागि प्रेषण गर्नुहोस्।'}},
      OUTCOME_AMENORRHEA:{severity:'warning',icon:'🟡',title:{en:'Amenorrhea',np:'Amenorrhea'},message:{en:'No menstruation for 3 months follows the amenorrhea branch.',np:'३ महिनादेखि महिनावारी नभएको अवस्था Amenorrhea शाखामा पर्छ।'},action:{en:'Further assessment and referral as indicated.',np:'आवश्यकताअनुसार थप मूल्याङ्कन तथा प्रेषण गर्नुहोस्।'}},
      OUTCOME_PID_CANCER_RETAINED_PLACENTA_POSTPARTUM:{severity:'danger',icon:'🚨',title:{en:'PID / Cancer / Retained Placenta / Post-partum Infection',np:'PID / Cancer / Retained placenta / Post-partum infection'},message:{en:'The source algorithm lists these causes when vaginal discharge occurs with relevant pregnancy/post-partum context.',np:'सम्बन्धित गर्भावस्था वा सुत्केरी अवस्थासँग vaginal discharge हुँदा स्रोत एल्गोरिदमले यी कारणहरू उल्लेख गर्छ।'},action:{en:'Assess urgently and refer/treat according to the applicable current protocol.',np:'तुरुन्त मूल्याङ्कन गरी लागू हुने हालको प्रोटोकलअनुसार प्रेषण/उपचार गर्नुहोस्।'}},
      OUTCOME_ABNORMAL_UTERINE_BLEEDING:{severity:'warning',icon:'🟠',title:{en:'Abnormal Uterine Bleeding',np:'Abnormal Uterine Bleeding'},message:{en:'The source algorithm directs this presentation to abnormal uterine bleeding.',np:'स्रोत एल्गोरिदमले यस अवस्थालाई Abnormal Uterine Bleeding तर्फ निर्देश गर्छ।'},action:{en:'Evaluate the cause and manage according to current guidance.',np:'कारण मूल्याङ्कन गरी हालको मार्गदर्शनअनुसार व्यवस्थापन गर्नुहोस्।'}},
      OUTCOME_FURTHER_ASSESSMENT:{severity:'warning',icon:'🟡',title:{en:'Further Assessment',np:'थप मूल्याङ्कन'},message:{en:'The source pathway does not give a specific endpoint at this branch.',np:'स्रोत एल्गोरिदमले यस शाखामा निश्चित endpoint दिएको छैन।'},action:{en:'Perform further clinical assessment and referral as appropriate.',np:'आवश्यकताअनुसार थप क्लिनिकल मूल्याङ्कन तथा प्रेषण गर्नुहोस्।'}}
